-- Low-carb photo identities. Only recipeCode changes; nutritional snapshots are retained.
-- Shared recipes and photos in other menus remain unchanged.
UPDATE meal_plan_templates SET weekly_menu=JSON_SET(weekly_menu, '$.days[0].meals[1].recipeCode', 'recipe-450') WHERE demo_code='low-carb' AND JSON_VALID(weekly_menu) AND JSON_UNQUOTE(JSON_EXTRACT(weekly_menu, '$.days[0].meals[1].recipeCode'))='recipe-019' AND JSON_UNQUOTE(JSON_EXTRACT(weekly_menu, '$.days[0].meals[1].name'))=CONVERT(0xd09ad0b8d181d0b5d0bbd0be20d0bcd0bbd18fd0bad0be20d18120d0bed180d0b5d185d0b8 USING utf8mb4);
UPDATE meal_plan_templates SET original_weekly_menu=JSON_SET(original_weekly_menu, '$.days[0].meals[1].recipeCode', 'recipe-450') WHERE demo_code='low-carb' AND JSON_VALID(original_weekly_menu) AND JSON_UNQUOTE(JSON_EXTRACT(original_weekly_menu, '$.days[0].meals[1].recipeCode'))='recipe-019' AND JSON_UNQUOTE(JSON_EXTRACT(original_weekly_menu, '$.days[0].meals[1].name'))=CONVERT(0xd09ad0b8d181d0b5d0bbd0be20d0bcd0bbd18fd0bad0be20d18120d0bed180d0b5d185d0b8 USING utf8mb4);
UPDATE user_meal_plans p JOIN meal_plan_templates t ON t.id=p.source_template_id SET p.weekly_menu=JSON_SET(p.weekly_menu, '$.days[0].meals[1].recipeCode', 'recipe-450') WHERE t.demo_code='low-carb' AND JSON_VALID(p.weekly_menu) AND JSON_UNQUOTE(JSON_EXTRACT(p.weekly_menu, '$.days[0].meals[1].recipeCode'))='recipe-019' AND JSON_UNQUOTE(JSON_EXTRACT(p.weekly_menu, '$.days[0].meals[1].name')) IN (CONVERT(0xd09ad0b8d181d0b5d0bbd0be20d0bcd0bbd18fd0bad0be20d18120d0bed180d0b5d185d0b8 USING utf8mb4), CONCAT(CONVERT(0xd09bd0b8d187d0b5d0bd20d0b2d0b0d180d0b8d0b0d0bdd18220d0bdd0b020 USING utf8mb4), CONVERT(0xd09ad0b8d181d0b5d0bbd0be20d0bcd0bbd18fd0bad0be20d18120d0bed180d0b5d185d0b8 USING utf8mb4)));
UPDATE meal_plan_templates SET weekly_menu=JSON_SET(weekly_menu, '$.days[6].meals[0].recipeCode', 'recipe-451') WHERE demo_code='low-carb' AND JSON_VALID(weekly_menu) AND JSON_UNQUOTE(JSON_EXTRACT(weekly_menu, '$.days[6].meals[0].recipeCode'))='recipe-366' AND JSON_UNQUOTE(JSON_EXTRACT(weekly_menu, '$.days[6].meals[0].name'))=CONVERT(0xd0afd0b9d186d0b020d181d18ad18120d181d0b8d180d0b5d0bdd0b520d0b820d181d0bfd0b0d0bdd0b0d0ba USING utf8mb4);
UPDATE meal_plan_templates SET original_weekly_menu=JSON_SET(original_weekly_menu, '$.days[6].meals[0].recipeCode', 'recipe-451') WHERE demo_code='low-carb' AND JSON_VALID(original_weekly_menu) AND JSON_UNQUOTE(JSON_EXTRACT(original_weekly_menu, '$.days[6].meals[0].recipeCode'))='recipe-366' AND JSON_UNQUOTE(JSON_EXTRACT(original_weekly_menu, '$.days[6].meals[0].name'))=CONVERT(0xd0afd0b9d186d0b020d181d18ad18120d181d0b8d180d0b5d0bdd0b520d0b820d181d0bfd0b0d0bdd0b0d0ba USING utf8mb4);
UPDATE user_meal_plans p JOIN meal_plan_templates t ON t.id=p.source_template_id SET p.weekly_menu=JSON_SET(p.weekly_menu, '$.days[6].meals[0].recipeCode', 'recipe-451') WHERE t.demo_code='low-carb' AND JSON_VALID(p.weekly_menu) AND JSON_UNQUOTE(JSON_EXTRACT(p.weekly_menu, '$.days[6].meals[0].recipeCode'))='recipe-366' AND JSON_UNQUOTE(JSON_EXTRACT(p.weekly_menu, '$.days[6].meals[0].name')) IN (CONVERT(0xd0afd0b9d186d0b020d181d18ad18120d181d0b8d180d0b5d0bdd0b520d0b820d181d0bfd0b0d0bdd0b0d0ba USING utf8mb4), CONCAT(CONVERT(0xd09bd0b8d187d0b5d0bd20d0b2d0b0d180d0b8d0b0d0bdd18220d0bdd0b020 USING utf8mb4), CONVERT(0xd0afd0b9d186d0b020d181d18ad18120d181d0b8d180d0b5d0bdd0b520d0b820d181d0bfd0b0d0bdd0b0d0ba USING utf8mb4)));
